package jp.takukairo;
import java.util.*;
import org.junit.jupiter.api.Test;
import jp.takukairo.importsession.*;
import static jp.takukairo.common.Json.*;
import static org.junit.jupiter.api.Assertions.*;
class ImportBoundaryTest {
 final ImportBoundary boundary=new ImportBoundary();
 ImportBoundary.Member member(long id,long source,String fingerprint,String table,String date){return new ImportBoundary.Member(id,source,fingerprint,map("scenarioName","A","tableName",table,"tableDates",List.of(map("playedOn",date)),"participations",List.of(map("personName","人物","pcName","PC","role","PL"))),Map.of());}
 @Test void copiedSourcesNeverSupplyIndependentEvidence(){var r=boundary.evaluate(List.of(member(1,1,"copy","A","2026-01-01"),member(2,2,"copy","A","2026-01-01"))).getFirst();assertEquals("E0",r.get("evidenceLevel"));assertEquals(false,r.get("automaticMerge"));}
 @Test void equivalentRecordsAcrossFormatsArePotentialCopies(){var r=boundary.evaluate(List.of(member(1,1,"md","A","2026-01-01"),member(2,2,"html","A","2026-01-01"))).getFirst();assertEquals("E0",r.get("evidenceLevel"));}
 @Test void independentDatesAndParticipantRecordsOnlyProposeExplicitConfirmation(){var r=boundary.evaluate(List.of(member(1,1,"source","A","2026-01-01"),member(2,1,"source","B","2026-01-01"))).getFirst();assertEquals("E2",r.get("evidenceLevel"));assertEquals(true,r.get("requiresSameTableConfirmation"));assertEquals(false,r.get("automaticMerge"));}
 @Test void differentDatesAloneDoNotProveSeparateTablesAndPairsNeverFormUnion(){var r=boundary.evaluate(List.of(member(1,1,"x","T","2026-01-01"),member(2,1,"x","T","2026-01-02"),member(3,1,"x","T","2026-01-03")));assertEquals(3,r.size());assertTrue(r.stream().allMatch(x->"E1".equals(x.get("evidenceLevel"))));assertTrue(r.stream().allMatch(x->((List<?>)x.get("candidateIds")).size()==2));}
 @Test void explicitSeparateScopesAreC1(){var a=member(1,1,"x","T1","2026-01-01");var b=member(2,1,"x","T2","2026-01-01");var r=boundary.evaluate(List.of(new ImportBoundary.Member(a.candidateId(),a.sourceId(),a.sourceFingerprint(),a.data(),map("scopeEvidenceId","heading-1")),new ImportBoundary.Member(b.candidateId(),b.sourceId(),b.sourceFingerprint(),b.data(),map("scopeEvidenceId","heading-2")))).getFirst();assertEquals("C1",r.get("conflict"));}
 @Test void explicitSameTableAssemblyKeepsParticipantsAndConflicts(){var p=new ImportParser().parse("x.md","# シナリオ: A\n## 卓名: T\n### 参加者記録\nPL: 人物1\n### その他\nPL: 人物2\nシナリオ: B");assertEquals(1,p.size());assertEquals(2,list(p.getFirst().data().get("participations")).size());assertEquals("A",p.getFirst().data().get("scenarioName"));assertFalse(list(p.getFirst().inference().get("conflicts")).isEmpty());}

 @Test void unrelatedScenariosDoNotBecomePairConflicts(){var a=member(1,1,"x","A","2026-01-01");var data=object(write(a.data()));data.put("scenarioName","Unrelated");data.put("participations",List.of());data.put("tableDates",List.of(map("playedOn","2026-02-01")));assertTrue(boundary.evaluate(List.of(a,new ImportBoundary.Member(2,1,"x",data,Map.of()))).isEmpty());}
 @Test void noParticipantRecordIsUniversallyRequiredForIndependentRecordingAndDateEvidence(){var a=member(1,1,"x","A","2026-01-01");var b=member(2,1,"x","B","2026-01-01");var da=object(write(a.data()));var db=object(write(b.data()));da.put("participations",List.of());db.put("participations",List.of());da.put("recordingUrl","https://example.test/recording");db.put("recordingUrl","https://example.test/recording");assertEquals("E2",boundary.evaluate(List.of(new ImportBoundary.Member(1,1,"x",da,Map.of()),new ImportBoundary.Member(2,1,"x",db,Map.of()))).getFirst().get("evidenceLevel"));}

 @Test void wholeGroupDoesNotPromoteAnUnprovenEndToEndPair(){var a=member(1,1,"x","A","2026-01-01");var b=member(2,1,"x","B","2026-01-01");var c=member(3,1,"x","C","2026-01-02");var group=boundary.evaluateGroup(List.of(a,b,c));assertEquals("E0",group.get("evidenceLevel"));assertFalse(list(group.get("counterEvidence")).isEmpty());assertEquals(false,group.get("automaticMerge"));}
 @Test void wholeGroupRejectsHiddenSeparateScopesEvenIfOtherPairsHaveEvidence(){var a=member(1,1,"x","A","2026-01-01");var b=member(2,2,"y","B","2026-01-01");var c=member(3,1,"x","C","2026-01-01");var one=new ImportBoundary.Member(a.candidateId(),a.sourceId(),a.sourceFingerprint(),a.data(),map("explicitScopes",List.of(map("sourceId",1,"scopeEvidenceId","scope1"))));var three=new ImportBoundary.Member(c.candidateId(),c.sourceId(),c.sourceFingerprint(),c.data(),map("explicitScopes",List.of(map("sourceId",1,"scopeEvidenceId","scope3"))));assertEquals(false,boundary.evaluateGroup(List.of(one,b,three)).get("canMerge"));}
 @Test void noScenarioNameIsRequiredWhenIndependentRecordsAndDatesAgree(){var a=member(1,1,"x","A","2026-01-01");var b=member(2,1,"x","B","2026-01-01");a.data().put("scenarioName","");b.data().put("scenarioName","");assertEquals("E2",boundary.evaluateGroup(List.of(a,b)).get("evidenceLevel"));}
 @Test void onDemandIncidentPairsKeepAllEvidenceAndCounterevidence(){
  var group=List.of(member(5,1,"original","A","2026-01-01"),member(3,1,"original","B","2026-01-01"),member(9,2,"copy","A","2026-01-01"),new ImportBoundary.Member(11,1,"original",member(11,1,"x","T","2026-01-02").data(),map("scopeEvidenceId","separate")));
  var all=boundary.evaluate(group);for(var member:group){var expected=all.stream().filter(p->((List<?>)p.get("candidateIds")).contains(member.candidateId())).map(p->{var d=new LinkedHashMap<>(p);var ids=((List<?>)p.get("candidateIds")).stream().map(x->((Number)x).longValue()).sorted().toList();d.put("candidateIds",ids);return write(d);}).toList();assertEquals(new HashSet<>(expected),new HashSet<>(boundary.evaluateFor(member.candidateId(),group).stream().map(jp.takukairo.common.Json::write).toList()));}
 }

}
